            if 0<=ni<h and 0<=nj<w and not seen[ni][nj] and g[ni][nj]==val:
                seen[ni][nj]=True;q.append((ni,nj))
    return [[4 if g[i][j]==val and not seen[i][j] else g[i][j] for j in range(w)] for i in range(h)]
